INSERT INTO comments (issue_id, team_id, author_id, body, created_at) SELECT i.id, i.team_id, 'alan', 'Reordering 50 rows sends 14 KB today. Most of it is dynamics we already have.', i.created_at + (now() - i.created_at) * 0.35 FROM issues i JOIN teams t ON t.id = i.team_id WHERE t.key = 'ENG' AND i.number = 15;
INSERT INTO comments (issue_id, team_id, author_id, body, created_at) SELECT i.id, i.team_id, 'grace', 'Found it: `o` entries carry the item even when only its position changed. Fix is in review soon.', i.created_at + (now() - i.created_at) * 0.65 FROM issues i JOIN teams t ON t.id = i.team_id WHERE t.key = 'ENG' AND i.number = 15;
