Repro: sort the jobs table by state and watch the SSE stream.', 'in_progress', 1, 'grace', 'alan', now() - interval '3 days' - interval '555 minutes', now() - interval '3 days' - interval '555 minutes', NULL FROM teams WHERE key = 'ENG';
