-- Every issue starts with a created event; issues past todo get a status change.
SELECT id, team_id, coalesce(assignee_id, creator_id), 'status', 'Todo',
	CASE status WHEN 'in_progress' THEN 'In Progress' WHEN 'in_review' THEN 'In Review' WHEN 'done' THEN 'Done' ELSE 'Canceled' END,
	created_at + (now() - created_at) / 3
FROM issues WHERE status IN ('in_progress', 'in_review', 'done', 'canceled');

